import {replay,validateCards} from './domain.mjs';
const json=(v,status=200)=>new Response(JSON.stringify(v),{status,headers:{'content-type':'application/json; charset=utf-8','cache-control':'no-store'}});
const groupsOK=g=>Array.isArray(g)&&g.length>0&&g.length<=60&&new Set(g).size===g.length&&g.every(x=>typeof x==='string'&&x.trim()===x&&x.length>0&&x.length<=20);
const metaOK=b=>typeof b.name==='string'&&b.name.trim().length>0&&b.name.length<=120&&typeof b.date==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(b.date)&&!isNaN(Date.parse(b.date))&&new Date(b.date).toISOString().slice(0,10)===b.date;
export async function handle(request,env){try{
 const url=new URL(request.url),path=url.pathname.replace('/api/',''),db=env.DB;
 if(!db)return json({error:'資料庫尚未設定'},503);
 const token=request.headers.get('authorization')?.replace(/^Bearer /,''),admin=!!env.ADMIN_TOKEN&&token===env.ADMIN_TOKEN,operator=admin||(!!env.OPERATOR_TOKEN&&token===env.OPERATOR_TOKEN);
 if(!['state','cards','counts','trade'].includes(path)&&!operator)return json({error:'請輸入正確的工作人員密碼'},401);
 if(path.startsWith('admin/')&&!admin)return json({error:'需要引導師密碼'},403);
 if(request.method==='POST'&&request.headers.get('origin')&&request.headers.get('origin')!==url.origin)return json({error:'來源不符'},403);
 const settings=await db.prepare('SELECT * FROM settings WHERE id=1').first(),active=settings.active_activity;
 const id=admin&&path==='admin/state'&&url.searchParams.get('activity')?url.searchParams.get('activity'):active;
 const a=await db.prepare('SELECT * FROM activities WHERE id=?').bind(id).first();
 if(!a)return json({error:'活動不存在'},404);
 const rows=async aid=>(await db.prepare('SELECT * FROM trades WHERE activity_id=? ORDER BY id').bind(aid).all()).results;
 if(request.method==='GET'){
  if(path==='admin/activities')return json({activeId:active,activities:(await db.prepare('SELECT a.*, (SELECT count(*) FROM trades t WHERE t.activity_id=a.id AND t.voided=0) total FROM activities a ORDER BY event_date DESC,created_at DESC,id').all()).results});
  if(path==='state'||path==='admin/state'){
   const ts=await rows(id),r=replay(ts),result={activity:{id:a.id,name:a.name,date:a.event_date,archived:!!a.archived},activeId:active,phase:a.archived?'archived':a.phase,groups:JSON.parse(a.groups_json),state:r.state,history:r.history,total:r.total};
   if(admin&&path==='admin/state'){result.trades=ts;result.counts=r.counts;result.cardCount=(await db.prepare('SELECT count(*) n FROM activity_cards WHERE activity_id=?').bind(id).first()).n;result.cardSnapshot=(await db.prepare('SELECT id,name,economy,environment,society FROM activity_cards WHERE activity_id=? ORDER BY id').bind(id).all()).results;}
   if(a.phase==='reflection'||a.archived)result.events=r.events;return json(result);
  }
  if(path==='cards')return json((await db.prepare('SELECT id,name FROM activity_cards WHERE activity_id=? ORDER BY id').bind(active).all()).results);
  if(path==='counts')return json(replay(await rows(active)).counts);
 }
 if(request.method!=='POST')return json({error:'找不到此功能'},404);
 const body=await request.json();
 if(path==='admin/create'){
  if(!metaOK(body)||!groupsOK(body.groups)||!/^[-a-zA-Z0-9]{16,80}$/.test(body.id||''))return json({error:'請填寫有效活動名稱、日期與組別'},400);
  const existing=await db.prepare('SELECT id FROM activities WHERE id=?').bind(body.id).first();if(existing)return json({ok:true,id:existing.id,duplicate:true});
  // The batch atomically checks the expected current activity, snapshots cards and advances the pointer.
  const guard="(SELECT active_activity FROM settings WHERE id=1)=? AND EXISTS(SELECT 1 FROM activities WHERE id=? AND archived=1)";
  const out=await db.batch([
   db.prepare(`INSERT INTO activities(id,name,event_date,groups_json) SELECT ?,?,?,? WHERE ${guard}`).bind(body.id,body.name.trim(),body.date,JSON.stringify(body.groups),body.activityId||'',body.activityId||''),
   db.prepare('INSERT INTO activity_cards SELECT ?,id,name,economy,environment,society FROM activity_cards WHERE activity_id=? AND EXISTS(SELECT 1 FROM activities WHERE id=?)').bind(body.id,active,body.id),
   db.prepare('UPDATE settings SET active_activity=? WHERE id=1 AND active_activity=? AND EXISTS(SELECT 1 FROM activities WHERE id=?)').bind(body.id,active,body.id)
  ]);
  return out[0].meta.changes?json({ok:true,id:body.id}):json({error:'請先封存目前活動，再建立下一場；若已切換請重新整理'},409);
 }
 if(path==='trade'){
  if(!/^[-a-zA-Z0-9]{16,80}$/.test(body.requestId||''))return json({error:'交易識別碼不正確'},400);
